START TRANSACTION;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (361, 'reglas_intro_cards', 'cards', '[{"icon": "BookOpen", "title": "Reglas USGA / FMG", "body": "Rigen las Reglas de Golf de la USGA adoptadas por la FMG, más las Condiciones de la Competencia y Reglas Locales del 71º Torneo Anual Club Campestre Saltillo 2026 (03 al 12 de septiembre), que dejan sin efecto cualquier otra regla local impresa en el score card del Club u otros documentos."}, {"icon": "Gavel", "title": "Árbitro del Torneo", "body": "Sr. Alberto Glez. Margain — Asistencia de Reglas: Tel. 871 235 3828. La penalidad por infringir cualquiera de las presentes condiciones es de dos golpes."}, {"icon": "Clock", "title": "Ritmo de juego", "body": "Par time de 18 hoyos: 4:50 hrs. Retraso injustificado: 1 golpe la primera vez, 2 golpes la segunda y descalificación la tercera. Grupo retrasado: 45 segundos el primer jugador en turno y 40 segundos cada jugador restante."}, {"icon": "AlertTriangle", "title": "Salidas y entrega de tarjeta", "body": "Hasta 5 minutos de retraso en la mesa de salida: dos golpes de penalidad; después de 5 minutos: descalificación, en cualquier sistema de juego. La tarjeta se entrega en un máximo de 15 minutos, en el toldo atrás del green del hoyo 18."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  content = VALUES(content),
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (361, 'reglas_locales', 'accordion', '[{"titulo": "Responsabilidad del jugador", "contenido": "ES RESPONSABILIDAD DEL JUGADOR CONOCER LAS REGLAS DE GOLF, LAS CONDICIONES DE LA COMPETENCIA Y LAS REGLAS LOCALES.\\nRegirán las Reglas de Golf de la USGA adoptadas por la FMG, así como las presentes Condiciones de Competencia y Reglas Locales, mismas que dejan sin efecto otras utilizadas en otros torneos, incluyendo las propias del score card del Club o cualquier otro documento.\\nSe designa al Sr. Alberto Glez. Margain como Árbitro del Torneo. Asistencia de Reglas: Tel. 871 235 3828.\\nLa penalidad por infringir alguna de las presentes será de dos golpes."}, {"titulo": "Hándicaps (R3.3)", "contenido": "Además de lo ya publicado en convocatoria: el Comité será el encargado de registrar los hándicaps de los jugadores y ubicarlos en su categoría correspondiente, y tiene la facultad de ajustar un hándicap de ser necesario. Si un jugador sabe que el Comité cometió un error con su hándicap deberá informarlo lo más pronto posible. El Comité se reserva el derecho de aceptar la validez del hándicap."}, {"titulo": "Cartas de hándicap", "contenido": "El Comité se reserva el derecho de validar o invalidar la carta, esto si las tarjetas del jugador no corresponden al hándicap de la carta."}, {"titulo": "Tope o ajuste de score", "contenido": "Si un jugador(a) en alguna categoría que se juegue con hándicap rebasa score de 67 golpes o 41 puntos en Stableford, será ajustado siendo éste el tope de ajuste de score. En caso de reincidir, el Comité se reserva el derecho de ajustar su hándicap al mínimo de la categoría o menor, permaneciendo en la misma categoría."}, {"titulo": "Rondas", "contenido": "Se jugarán rondas de 18 hoyos; sin embargo, el Comité se reserva el derecho de reducir la cantidad de hoyos en alguna de ellas debido al mal tiempo."}, {"titulo": "Descalificación", "contenido": "Un jugador descalificado por cualquier regla no tendrá derecho de seguir participando en la competencia en rondas posteriores. Se hará acreedor a los premios obtenidos en la competencia antes de la descalificación y podrá seguir participando en competencias externas a las rondas, rifas y sorteos."}, {"titulo": "Hora de salida (R5.3a)", "contenido": "Los jugadores deberán estar en su área de salida, listos para jugar, a la hora estipulada, independientemente del orden en que les toque salir. Si el jugador se presenta hasta con cinco minutos de retraso a su mesa de salida, tendrá dos golpes de castigo. Si se presenta después de los cinco minutos, será descalificado de la competencia, en cualquier sistema de juego."}, {"titulo": "Retraso injustificado (R5.6)", "contenido": "Par time para 18 hoyos: 4:50 hrs. Penalidad por retraso injustificado: un golpe en la primera ocasión, dos golpes en la segunda y descalificación en la tercera. Cuando un grupo se retrase, el tiempo para ejecutar su golpe es de 45 segundos para el primer jugador en turno y de 40 segundos para cada jugador restante."}, {"titulo": "Entrega de scores (R3.3)", "contenido": "El jugador deberá entregar la tarjeta lo más pronto posible; el tiempo máximo para entregarla es de 15 minutos. La recepción de scores será en el toldo atrás del green del hoyo 18."}, {"titulo": "Obstrucciones temporales inamovibles (MRL F-23)", "contenido": "Todas las instalaciones de publicidad, anuncios, carpas, pantallas, torres de iluminación, cámaras de video y gradas que no se puedan mover, así como los vehículos en exhibición instalados especialmente para este torneo, se consideran Obstrucciones Temporales Inamovibles y podrán tener alivio sin penalidad, incluyendo la línea de juego, con alivio a cualquier lado de la obstrucción."}, {"titulo": "Zonas o círculos de dropeo (MRL E-1)", "contenido": "Son una opción más de alivio a la regla aplicable.\\n• Hoyo 1: para una bola en el área de penalidad ubicada atrás del lago, y una más para una bola en el camino deprimido del túnel.\\n• Hoyo 3: para una bola en el terreno en reparación ubicado del lado izquierdo del green, pegado al canal.\\n• Hoyo 3: para una bola en el área de snack.\\n• Hoyo 6: para una bola en el área de snack.\\n• Hoyo 14: para una bola en el área de snack."}, {"titulo": "Zona de juego prohibido (MRL E-8.1)", "contenido": "El vivero ubicado del lado izquierdo del hoyo 11, delimitado con estacas verdes."}, {"titulo": "Ranuras alrededor del green (MRL F-19)", "contenido": "Ésta se ubica en el collarín o french del green, por lo tanto está ubicada en el área general. El jugador podrá tomar alivio si su bola reposa o toca la ranura; el alivio es DROPEANDO la bola en el punto de alivio más cercano más el largo de un palo, sin acercarse al hoyo y sin cambiar de área del campo."}, {"titulo": "Equipo para medir distancia (R4.3a)", "contenido": "Está permitido. No deberá tener alguna función adicional que pueda medir altura, viento, humedad, temperatura o similar. Penalidad: descalificación."}, {"titulo": "Obstrucciones inamovibles (R16)", "contenido": "Postes metálicos de la malla de protección de los hoyos 2 y 8, caminos con superficie artificial, muros pegados a éstos y jardineras rodeadas por éstos; controles de riego, aspersores, bancas de descanso, casetas de bombeo, tapas de registro de cemento y metal y snacks. Todas éstas tienen alivio sin penalidad al punto de alivio más cercano más el largo de un palo y no más cerca del hoyo."}, {"titulo": "Obstrucciones inamovibles alrededor de los greenes (MRL F-5)", "contenido": "Cuando en la línea de juego exista intervención por una obstrucción que se encuentre dentro de dos palos de la bola, y ésta esté dentro del largo de dos palos del green, habrá alivio sin penalidad dropeando la bola lo más cerca posible de su posición original más un palo (R16), siempre que: a) no se acerque al hoyo, b) evite la intervención y c) la bola repose en el área general."}, {"titulo": "Objetos integrantes del campo (R8.1a)", "contenido": "Todos los cajetes de árboles, muros de contención, todos los objetos que delimitan el campo y los muros de áreas de penalidad."}, {"titulo": "Condiciones anormales del campo (R16)", "contenido": "Áreas encerradas con líneas o puntos blancos definen terreno en reparación; hormigueros, agujeros de animal, agua temporal y uniones de pasto recién sembrado. Las áreas marcadas como terreno en reparación que terminan en caminos con superficie artificial son parte de la misma condición."}, {"titulo": "Bola enterrada (R16.3)", "contenido": "Una bola tendrá alivio sin penalidad si está enterrada por su propio impacto a través del campo, en pasto en área general."}, {"titulo": "Áreas de penalidad (R17)", "contenido": "Se encuentran identificadas por estacas y/o líneas pintadas de rojo (laterales). Los muros que las delimitan se consideran parte integrante del campo. Las líneas tienen prioridad sobre las estacas."}, {"titulo": "Fuera de límites internos hoyos 3 y 7", "contenido": "En el hoyo 3, del lado derecho en dirección al fairway del hoyo 7, delimitado por estacas blancas: si la bola reposa en el campo pero después de las estacas, es fuera de límites. En el hoyo 7, del lado izquierdo en dirección al fairway del hoyo 8, delimitado por estacas blancas: si la bola reposa en el campo después de las estacas, es fuera de límites. Para el juego de otro hoyo, estas estacas son obstrucciones movibles."}, {"titulo": "Fuera de límites", "contenido": "Está marcado en la parte inferior interna con estacas, líneas blancas, bardas, cercas, postes o mallas. Las líneas tienen prioridad sobre cualquier otra cosa."}, {"titulo": "Teléfonos celulares", "contenido": "Se podrá usar a discreción en modo avión, sin distraer a los compañeros de grupo, sin retrasar el juego, para solicitar reglas o ver los resultados del torneo."}, {"titulo": "Música", "contenido": "Está prohibido escuchar música en cualquier dispositivo. Penalidad: primera vez amonestación, segunda vez dos golpes de penalidad (en Stableford reducción de dos puntos de su score final) y tercera vez descalificación."}, {"titulo": "Cierre de la competencia", "contenido": "La competencia se considera cerrada en el momento del inicio de la ceremonia de premiación."}, {"titulo": "Otras recomendaciones", "contenido": "Recuerde que las Reglas contemplan:\\n• Marcar su bola para identificación.\\n• No acomodar la bola en ningún momento.\\n• No hay dadas, hay que embocar.\\n• No se puede cambiar la bola sobre el green ni en ninguna otra parte, a menos que una Regla lo permita.\\n• No se pueden usar más de 14 bastones.\\n• Sólo podrá contratar a un caddie a la vez.\\n• No se puede dar o recibir consejo."}, {"titulo": "Desempates", "contenido": "Especificado en convocatoria. Si por falta de luz natural algún desempate no pudiera llevarse a cabo en el campo, el segundo criterio será por comparación de tarjetas."}, {"titulo": "Suspensión", "contenido": "En caso de ser necesaria la suspensión de la ronda, ésta será avisada por medio de un toque prolongado de sirena, y dos toques para la reanudación."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  content = VALUES(content),
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

